function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'MyCalendarThree' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with MyCalendarThree and no arguments.';
  if (operations.length - 1 > 400) return 'At most 400 calls to book.';
  for (let i = 1; i < operations.length; i++) {
    if (operations[i] !== 'book') return 'Only book can follow the constructor.';
    const call = args[i];
    if (!Array.isArray(call) || call.length !== 2 || !Number.isInteger(call[0]) || !Number.isInteger(call[1])) return 'book takes two whole numbers.';
    if (call[0] < 0 || call[0] >= call[1] || call[1] > 1000000000) return 'book needs 0 <= startTime < endTime <= 10^9.';
  }
  return null;
}

