class MyCalendarThree {
  constructor() {
    this.change = new Map();
    this.times = [];
  }

  book(startTime, endTime) {
    this.addBoundary(startTime, 1);
    this.addBoundary(endTime, -1);
    let active = 0;
    let best = 0;
    for (const time of this.times) {
      active += this.change.get(time);
      best = Math.max(best, active);
    }
    return best;
  }

  addBoundary(time, delta) {
    if (!this.change.has(time)) {
      let low = 0;
      let high = this.times.length;
      while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (this.times[mid] < time) {
          low = mid + 1;
        } else {
          high = mid;
        }
      }
      this.times.splice(low, 0, time);
      this.change.set(time, 0);
    }
    this.change.set(time, this.change.get(time) + delta);
  }
}

