class MyCalendarThree {
  constructor() {
    this.events = [];
  }
  book(startTime, endTime) {
    this.events.push([startTime, endTime]);
    // The deepest overlap always begins at some event's start, so test only those moments.
    let most = 0;
    for (const [moment] of this.events) {
      let count = 0;
      for (const [s, e] of this.events) if (s <= moment && moment < e) count++;
      most = Math.max(most, count);
    }
    return most;
  }
}

