function generate(rand, size) {
  const large = size === 'large';
  const calls = large ? 400 : 1 + Math.floor(rand() * 12);
  const limit = large ? 1000000000 : 4 + Math.floor(rand() * 20);
  // A shared pool of moments makes many events start or end at exactly the same time.
  const pool = Array.from({ length: large ? 300 : 6 }, () => Math.floor(rand() * (limit + 1))).sort((a, b) => a - b);
  const operations = ['MyCalendarThree'];
  const args = [[]];
  for (let i = 0; i < calls; i++) {
    let start;
    let end;
    if (rand() < 0.4) {
      const a = pool[Math.floor(rand() * pool.length)];
      const b = pool[Math.floor(rand() * pool.length)];
      start = Math.min(a, b);
      end = Math.max(a, b);
      if (start === end) {
        if (end < limit) end++;
        else start--;
      }
    } else {
      start = Math.floor(rand() * limit);
      end = start + 1 + Math.floor(rand() * rand() * (limit - start));
    }
    operations.push('book');
    args.push([start, end]);
  }
  return [operations, args];
}
